import React, { useState, useEffect } from 'react';
import { Box, Typography, IconButton, InputBase, Avatar, Drawer } from '@mui/material';
import MenuIcon   from '@mui/icons-material/Menu';
import SearchIcon from '@mui/icons-material/Search';

import { translateCity } from '../../i18n/translations';
import styles from './Header.module.scss';

// ── LocalStorage helpers ──────────────────────────────────────────────────────
const STORAGE_KEY = 'weatherapp_users';
const SESSION_KEY = 'weatherapp_session';

const getUsers = () => JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
const saveUsers = (users) => localStorage.setItem(STORAGE_KEY, JSON.stringify(users));
const getSession = () => JSON.parse(localStorage.getItem(SESSION_KEY) || 'null');
const saveSession = (user) => localStorage.setItem(SESSION_KEY, JSON.stringify(user));
const clearSession = () => localStorage.removeItem(SESSION_KEY);

// ── Auth Modal ────────────────────────────────────────────────────────────────
const AuthModal = ({ mode: authMode, themeMode, onClose, onSuccess, t }) => {
  const [view, setView] = useState(authMode); // 'login' | 'register'
  const [form, setForm] = useState({ name: '', email: '', password: '', confirm: '' });
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);

  const set = (field) => (e) => setForm((f) => ({ ...f, [field]: e.target.value }));

  const validate = () => {
    const errs = {};
    if (view === 'register' && !form.name.trim()) errs.name = t.auth.errName;
    if (!form.email.includes('@')) errs.email = t.auth.errEmail;
    if (form.password.length < 6) errs.password = t.auth.errPassword;
    if (view === 'register' && form.password !== form.confirm) errs.confirm = t.auth.errConfirm;
    return errs;
  };

  const handleSubmit = () => {
    const errs = validate();
    if (Object.keys(errs).length) { setErrors(errs); return; }
    setLoading(true);

    setTimeout(() => {
      const users = getUsers();
      if (view === 'login') {
        const user = users.find((u) => u.email === form.email && u.password === form.password);
        if (!user) { setErrors({ email: t.auth.errWrongAuth }); setLoading(false); return; }
        saveSession(user);
        onSuccess(user);
      } else {
        if (users.find((u) => u.email === form.email)) {
          setErrors({ email: t.auth.errEmailTaken }); setLoading(false); return;
        }
        const newUser = {
          id: Date.now(),
          name: form.name.trim(),
          email: form.email,
          password: form.password,
          avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(form.email)}`,
          joinedAt: new Date().toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' }),
          unit: 'c',
          notifications: true,
        };
        saveUsers([...users, newUser]);
        saveSession(newUser);
        onSuccess(newUser);
      }
      setLoading(false);
    }, 600);
  };

  const handleKey = (e) => { if (e.key === 'Enter') handleSubmit(); };

  return (
    <div className={styles.modalOverlay} onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className={`${styles.modal} ${themeMode === 'light' ? 'theme-light' : 'theme-dark'}`}>
        <button className={styles.modalClose} onClick={onClose}>✕</button>

        <div className={styles.modalTitle}>
          {view === 'login' ? t.auth.welcomeBack : t.auth.registration}
        </div>
        <div className={styles.modalSub}>
          {view === 'login' ? t.auth.loginSub : t.auth.registerSub}
        </div>

        {view === 'register' && (
          <div className={styles.fieldGroup}>
            <label className={styles.fieldLabel}>{t.auth.nameField}</label>
            <input
              className={`${styles.inputField} ${errors.name ? styles.error : ''}`}
              placeholder={t.auth.namePlaceholder}
              value={form.name}
              onChange={set('name')}
              onKeyDown={handleKey}
            />
            {errors.name && <div className={styles.errorMsg}>{errors.name}</div>}
          </div>
        )}

        <div className={styles.fieldGroup}>
          <label className={styles.fieldLabel}>{t.auth.emailField}</label>
          <input
            className={`${styles.inputField} ${errors.email ? styles.error : ''}`}
            type="email"
            placeholder="your@email.com"
            value={form.email}
            onChange={set('email')}
            onKeyDown={handleKey}
          />
          {errors.email && <div className={styles.errorMsg}>{errors.email}</div>}
        </div>

        <div className={styles.fieldGroup}>
          <label className={styles.fieldLabel}>{t.auth.passwordField}</label>
          <input
            className={`${styles.inputField} ${errors.password ? styles.error : ''}`}
            type="password"
            placeholder={view === 'register' ? t.auth.errPassword : '••••••••'}
            value={form.password}
            onChange={set('password')}
            onKeyDown={handleKey}
          />
          {errors.password && <div className={styles.errorMsg}>{errors.password}</div>}
        </div>

        {view === 'register' && (
          <div className={styles.fieldGroup}>
            <label className={styles.fieldLabel}>{t.auth.confirmField}</label>
            <input
              className={`${styles.inputField} ${errors.confirm ? styles.error : ''}`}
              type="password"
              placeholder={t.auth.confirmPlaceholder}
              value={form.confirm}
              onChange={set('confirm')}
              onKeyDown={handleKey}
            />
            {errors.confirm && <div className={styles.errorMsg}>{errors.confirm}</div>}
          </div>
        )}

        <button
          className={styles.btnPrimary}
          onClick={handleSubmit}
          disabled={loading}
          style={{ marginTop: 8, opacity: loading ? 0.7 : 1 }}
        >
          {loading ? t.auth.loading : view === 'login' ? t.auth.signIn : t.auth.signUp}
        </button>

        <div className={styles.modalSwitch}>
          {view === 'login' ? (
            <>
              {t.auth.noAccount}{' '}
              <span className={styles.modalLink} onClick={() => { setView('register'); setErrors({}); setForm({ name: '', email: '', password: '', confirm: '' }); }}>
                {t.auth.signUp}
              </span>
            </>
          ) : (
            <>
              {t.auth.haveAccount}{' '}
              <span className={styles.modalLink} onClick={() => { setView('login'); setErrors({}); setForm({ name: '', email: '', password: '', confirm: '' }); }}>
                {t.auth.signIn}
              </span>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

// ── Profile Drawer ────────────────────────────────────────────────────────────
const ProfileDrawer = ({ open, onClose, t, user, onLogin, onRegister, onLogout, onUserUpdate, mode }) => {
  const [drawerTab, setDrawerTab] = useState('profile');
  const [editing, setEditing]     = useState(false);
  const [draft, setDraft]         = useState('');

  useEffect(() => {
    if (user) setDraft(user.name);
  }, [user]);

  const handleSaveName = () => {
    if (!draft.trim()) return;
    const updated = { ...user, name: draft.trim() };
    const users = getUsers().map((u) => u.id === user.id ? updated : u);
    saveUsers(users);
    saveSession(updated);
    onUserUpdate(updated);
    setEditing(false);
  };

  const handleLogout = () => {
    clearSession();
    onLogout();
    onClose();
    setDrawerTab('profile');
  };

  // Tabs structure mapped to translated strings
  const TABS = [
    { id: 'profile',       label: t.profile.tabProfile },
    { id: 'notifications', label: t.profile.tabNotifications },
    { id: 'settings',      label: t.profile.tabSettings },
  ];

  return (
    <Drawer
      anchor="right"
      open={open}
      onClose={onClose}
      PaperProps={{ className: styles.drawerPaper }}
    >
      <div className={`${styles.drawerInner} ${mode === 'light' ? 'theme-light' : 'theme-dark'}`}>

        {/* Drawer Header */}
        <div className={styles.drawerHeader}>
          <span className={styles.drawerTitle}>
            {!user ? t.profile.account : TABS.find((tab) => tab.id === drawerTab)?.label}
          </span>
          <button className={styles.drawerClose} onClick={onClose}>✕</button>
        </div>

        {/* ── UNAUTHORIZED USER CONTENT ── */}
        {!user && (
          <>
            <div className={styles.profileCard}>
              <div className={styles.guestAvatar}>👤</div>
              <div className={styles.profileName} style={{ fontSize: 16 }}>{t.profile.notLoggedIn}</div>
              <div className={styles.profileSub}>{t.profile.loginForAccess}</div>
            </div>

            <div className={styles.authSection}>
              <button className={styles.btnPrimary} onClick={() => { onClose(); onLogin(); }}>
                {t.profile.signInBtn}
              </button>
              <button className={styles.btnSecondary} onClick={() => { onClose(); onRegister(); }}>
                {t.profile.signUpBtn}
              </button>
            </div>

            <div className={styles.divider} />

            <div className={styles.actionSection}>
              <button className={styles.actionBtn}>
                <span>ℹ️</span>
                <span>{t.profile.whatIsRegistration}</span>
                <span className={styles.actionArrow}>›</span>
              </button>
            </div>
          </>
        )}

        {/* ── AUTHORIZED USER CONTENT ── */}
        {user && (
          <>
            {/* Navigation Tab Bar */}
            <div className={styles.tabBar}>
              {TABS.map((tab) => (
                <button
                  key={tab.id}
                  className={`${styles.tab} ${drawerTab === tab.id ? styles.active : ''}`}
                  onClick={() => setDrawerTab(tab.id)}
                >
                  {tab.label}
                </button>
              ))}
            </div>

            {/* ── TAB: PROFILE ── */}
            {drawerTab === 'profile' && (
              <>
                <div className={styles.profileCard}>
                  <div className={styles.avatarWrap}>
                    <img
                      src={user.avatar}
                      alt="avatar"
                      className={styles.drawerAvatar}
                      onError={(e) => { e.target.src = `https://i.pravatar.cc/150?u=${user.email}`; }}
                    />
                    <div className={styles.avatarOnline} />
                  </div>

                  {editing ? (
                    <div className={styles.editRow}>
                      <input
                        className={styles.nameInput}
                        value={draft}
                        onChange={(e) => setDraft(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSaveName()}
                        autoFocus
                      />
                      <button className={styles.saveBtn} onClick={handleSaveName}>✓</button>
                    </div>
                  ) : (
                    <div className={styles.nameRow}>
                      <span className={styles.profileName}>{user.name}</span>
                      <button className={styles.editBtn} onClick={() => setEditing(true)}>✏️</button>
                    </div>
                  )}

                  <span className={styles.profileSub}>{user.email}</span>
                  <span className={styles.profileBadge}>{t.profile.userBadge}</span>
                </div>

                <div className={styles.infoSection}>
                  <div className={styles.sectionLabel}>{t.profile.infoTitle}</div>
                  <div className={styles.infoChip}>
                    <span>📅</span>
                    <span>{t.profile.joined.replace('{date}', user.joinedAt)}</span>
                  </div>
                  <div className={styles.infoChip}>
                    <span>🌍</span>
                    <span>{t.profile.locationLabel}</span>
                  </div>
                  <div className={styles.infoChip}>
                    <span>🌡️</span>
                    <span>{t.profile.unitsLabel.replace('{unit}', user.unit === 'f' ? '°F' : '°C')}</span>
                  </div>
                </div>

                <div className={styles.divider} />

                <div className={styles.actionSection}>
                  <button className={styles.actionBtn} onClick={() => setDrawerTab('settings')}>
                    <span>⚙️</span>
                    <span>{t.profile.accountSettings}</span>
                    <span className={styles.actionArrow}>›</span>
                  </button>
                  <button className={styles.actionBtn} onClick={() => setDrawerTab('notifications')}>
                    <span>🔔</span>
                    <span>{t.profile.notifTitle}</span>
                    <span className={styles.actionArrow}>›</span>
                  </button>
                </div>

                <div className={styles.divider} />

                <button className={styles.logoutBtn} onClick={handleLogout}>
                  <span>🚪</span>
                  <span>{t.profile.logoutBtn}</span>
                </button>
              </>
            )}

            {/* ── TAB: NOTIFICATIONS ── */}
            {drawerTab === 'notifications' && (
              <>
                <div className={styles.notifPanel}>
                  {[
                    { dot: '', text: 'Прогноз на завтра: очікується дощ після 15:00', time: '5 хв тому' },
                    { dot: 'warn', text: 'Вітер посилиться до 25 км/год ввечері', time: '1 год тому' },
                    { dot: 'success', text: 'Гарна погода для прогулянки сьогодні вранці!', time: 'Сьогодні, 08:00' },
                  ].map((n, i) => (
                    <div key={i} className={styles.notifItem}>
                      <div className={`${styles.notifDot} ${n.dot ? styles[n.dot] : ''}`} />
                      <div>
                        <div className={styles.notifText}>{n.text}</div>
                        <div className={styles.notifTime}>{n.time}</div>
                      </div>
                    </div>
                  ))}
                </div>

                <button className={styles.btnSecondary}>
                  {t.profile.markAllRead}
                </button>
              </>
            )}

            {/* ── TAB: SETTINGS ── */}
            {drawerTab === 'settings' && (
              <>
                <div className={styles.settingsPanel}>
                  <div className={styles.settingsPanelTitle}>{t.profile.accountSection}</div>

                  <div className={styles.settingRow}>
                    <span className={styles.settingLabel}>{t.profile.nameLabel}</span>
                    {editing ? (
                      <div style={{ display: 'flex', gap: 6 }}>
                        <input
                          className={styles.nameInput}
                          value={draft}
                          onChange={(e) => setDraft(e.target.value)}
                          onKeyDown={(e) => e.key === 'Enter' && handleSaveName()}
                          style={{ width: 110, fontSize: 13 }}
                        />
                        <button className={styles.saveBtn} onClick={handleSaveName} style={{ fontSize: 12, padding: '4px 8px' }}>✓</button>
                      </div>
                    ) : (
                      <span
                        style={{ fontSize: 13, color: 'var(--color-text-secondary)', cursor: 'pointer' }}
                        onClick={() => setEditing(true)}
                      >
                        {user.name} ✏️
                      </span>
                    )}
                  </div>

                  <div className={styles.settingRow}>
                    <span className={styles.settingLabel}>{t.profile.emailLabel}</span>
                    <span style={{ fontSize: 13, color: 'var(--color-text-muted)' }}>{user.email}</span>
                  </div>
                </div>

                <div className={styles.settingsPanel}>
                  <div className={styles.settingsPanelTitle}>{t.profile.displaySection}</div>
                  <div className={styles.settingRow}>
                    <span className={styles.settingLabel}>{t.profile.tempLabel}</span>
                    <select
                      className={styles.selectSm}
                      value={user.unit}
                      onChange={(e) => {
                        const updated = { ...user, unit: e.target.value };
                        const users = getUsers().map((u) => u.id === user.id ? updated : u);
                        saveUsers(users);
                        saveSession(updated);
                        onUserUpdate(updated);
                      }}
                    >
                      <option value="c">°C Цельсій</option>
                      <option value="f">°F Фаренгейт</option>
                    </select>
                  </div>
                </div>

                <div className={styles.settingsPanel}>
                  <div className={styles.settingsPanelTitle}>{t.profile.dangerZone}</div>
                  <div className={styles.settingRow}>
                    <span className={styles.settingLabel}>{t.profile.changePassword}</span>
                    <span style={{ fontSize: 13, color: '#4facfe', cursor: 'pointer' }}>{t.profile.changeBtn}</span>
                  </div>
                  <div className={styles.settingRow} style={{ border: 'none', paddingBottom: 0 }}>
                    <span className={styles.settingLabel}>{t.profile.deleteAccount}</span>
                    <span
                      style={{ fontSize: 13, color: '#e24b4a', cursor: 'pointer' }}
                      onClick={() => {
                        if (window.confirm(t.profile.deleteConfirm)) {
                          const users = getUsers().filter((u) => u.id !== user.id);
                          saveUsers(users);
                          handleLogout();
                        }
                      }}
                    >
                      {t.profile.deleteBtn}
                    </span>
                  </div>
                </div>

                <button className={styles.logoutBtn} onClick={handleLogout}>
                  <span>🚪</span>
                  <span>{t.profile.logoutBtn}</span>
                </button>
              </>
            )}
          </>
        )}

        <div className={styles.drawerFooter}>Weather App · v2.1.0</div>
      </div>
    </Drawer>
  );
};

// ── Header ────────────────────────────────────────────────────────────────────
const Header = ({ activeTab, city, mode, onMenuOpen, onToggleTheme, isMobile, t, onSearch }) => {
  const [query,       setQuery]       = useState('');
  const [profileOpen, setProfileOpen] = useState(false);
  const [authModal,   setAuthModal]   = useState(null);
  const [user,        setUser]        = useState(() => getSession());

  const handleSearch = () => {
    const trimmed = query.trim();
    if (trimmed) onSearch(trimmed);
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') handleSearch();
  };

  const handleAuthSuccess = (loggedUser) => {
    setUser(loggedUser);
    setAuthModal(null);
    setProfileOpen(true);
  };

  return (
    <>
      <Box className={styles.header}>
        <Box className={styles.left}>
          {isMobile && (
            <IconButton onClick={onMenuOpen} size="small" className={styles.burgerBtn}>
              <MenuIcon fontSize="small" />
            </IconButton>
          )}
          <Box>
            <Typography className={styles.title}>{t.pageTitles[activeTab]}</Typography>
            <Typography variant="caption" className={styles.city}>
              📍 {translateCity(city, t)}
            </Typography>
          </Box>
        </Box>

        <Box className={styles.right}>
          {!isMobile && (
            <Box className={styles.searchBox}>
              <SearchIcon
                className={styles.searchIcon}
                onClick={handleSearch}
                style={{ cursor: 'pointer' }}
              />
              <InputBase
                placeholder={t.header.searchPlaceholder}
                fullWidth
                className={styles.searchInput}
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                onKeyDown={handleKeyDown}
              />
            </Box>
          )}

          <Box onClick={onToggleTheme} className={styles.themeToggle}>
            {mode === 'dark' ? '☀️' : '🌙'}
          </Box>

          <Avatar
            src={user?.avatar || undefined}
            className={styles.avatar}
            onClick={() => setProfileOpen(true)}
            sx={{
              background: user ? undefined : 'linear-gradient(135deg, #4facfe, #00c6ff)',
              fontSize: '18px',
            }}
          >
            {!user && '👤'}
          </Avatar>
        </Box>
      </Box>

      <ProfileDrawer
        open={profileOpen}
        onClose={() => setProfileOpen(false)}
        t={t}
        user={user}
        mode={mode}
        onLogin={() => setAuthModal('login')}
        onRegister={() => setAuthModal('register')}
        onLogout={() => setUser(null)}
        onUserUpdate={(updated) => setUser(updated)}
      />

      {authModal && (
        <AuthModal
          mode={authModal}
          themeMode={mode}
          onClose={() => setAuthModal(null)}
          onSuccess={handleAuthSuccess}
          t={t}
        />
      )}
    </>
  );
};

export default Header;